local Plasterer = {}
local PRODUCTS = {
    plaster_wall = { name = "Ometana stena", limeCost = 3, sandCost = 3, time = 3, cost = 30, smoothness = 10, description = "Preprost omet." },
    polished_plaster = { name = "Polirani omet", limeCost = 5, sandCost = 2, time = 7, cost = 100, smoothness = 25, prestige = 3, description = "Gladko polirana površina." },
    fresco_base = { name = "Freska podlaga", limeCost = 8, sandCost = 4, time = 5, cost = 150, smoothness = 30, description = "Pripravljena podlaga za freske." },
    stucco = { name = "Štukatura", limeCost = 6, marbleCost = 2, time = 10, cost = 300, smoothness = 40, prestige = 10, description = "Luksuzna štukatura." },
    gilded_plaster = { name = "Pozlačeni omet", limeCost = 5, goldCost = 1, time = 14, cost = 500, smoothness = 35, prestige = 20, description = "Z zlatimi lističi." },
    mosaic_floor = { name = "Mozaik", tileCost = 10, limeCost = 3, time = 20, cost = 800, smoothness = 50, prestige = 25, happiness = 5, description = "Mozaik za tla." },
}
local BUILDINGS = {
    workshop = { name = "Ometarska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    lime_kiln = { name = "Apnena peč", cost = { gold = 500, wood = 200, stone = 200 }, upkeep = 12, limeProduction = 5 },
    plaster_studio = { name = "Ometarski atelje", cost = { gold = 1500, wood = 200, stone = 400 }, upkeep = 30, qualityBonus = 20 },
    royal_plastering = { name = "Kraljevsko ometarstvo", cost = { gold = 4000, wood = 400, stone = 800 }, upkeep = 80, qualityBonus = 35, prestigeBonus = 15 },
}
Plasterer.limeStock = 15; Plasterer.sandStock = 15; Plasterer.marbleStock = 5; Plasterer.goldStock = 3; Plasterer.tileStock = 8
Plasterer.productStock = {}; Plasterer.buildings = {}; Plasterer.plasterer = nil; Plasterer.activeMaking = {}; Plasterer.totalProducts = 0; Plasterer.dayTimer = 0
function Plasterer.init() Plasterer.limeStock=15; Plasterer.sandStock=15; Plasterer.marbleStock=5; Plasterer.goldStock=3; Plasterer.tileStock=8; Plasterer.productStock={}; Plasterer.buildings={}; Plasterer.plasterer=nil; Plasterer.activeMaking={}; Plasterer.totalProducts=0; Plasterer.dayTimer=0; print("[Plasterer] Royal Plasterer & Decorator System initialized (6 products, 4 buildings)") end
function Plasterer.hirePlasterer(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Plasterer.plasterer={name=n or ("Ometar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ometar najet: %s (spretnost: %d)",Plasterer.plasterer.name,s),"success") end; return true end
function Plasterer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Plasterer.build(id) local ok,e=Plasterer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Plasterer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Plasterer.getQualityBonus() local b=0; for _,bd in ipairs(Plasterer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Plasterer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.limeCost and Plasterer.limeStock<(d.limeCost or 0) then return false,"Premalo apna" end; if d.sandCost and Plasterer.sandStock<(d.sandCost or 0) then return false,"Premalo peska" end; if d.marbleCost and Plasterer.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.goldCost and Plasterer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.tileCost and Plasterer.tileStock<(d.tileCost or 0) then return false,"Premalo ploščic" end; if #Plasterer.buildings==0 then return false,"Potrebna delavnica" end; if not Plasterer.plasterer then return false,"Potreben ometar" end; return true end
function Plasterer.make(pt) local ok,e=Plasterer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.limeCost then Plasterer.limeStock=Plasterer.limeStock-d.limeCost end; if d.sandCost then Plasterer.sandStock=Plasterer.sandStock-d.sandCost end; if d.marbleCost then Plasterer.marbleStock=Plasterer.marbleStock-d.marbleCost end; if d.goldCost then Plasterer.goldStock=Plasterer.goldStock-d.goldCost end; if d.tileCost then Plasterer.tileStock=Plasterer.tileStock-d.tileCost end; local t=d.time; if Plasterer.plasterer then t=math.max(1,t-math.floor(Plasterer.plasterer.skill/12)) end; table.insert(Plasterer.activeMaking,{id="plaster_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,smoothness=d.smoothness or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ometanje: %s (%d dni)",d.name,t),"info") end; return true end
function Plasterer.completeMaking(m) local q=1.0+(Plasterer.getQualityBonus()/100); if Plasterer.plasterer then q=q+(Plasterer.plasterer.skill/200) end; q=math.min(2.0,q); Plasterer.productStock[m.productType]=(Plasterer.productStock[m.productType] or 0)+1; Plasterer.totalProducts=Plasterer.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Plasterer.plasterer then Plasterer.plasterer.itemsMade=Plasterer.plasterer.itemsMade+1; if math.random()<0.15 then Plasterer.plasterer.skill=math.min(100,Plasterer.plasterer.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Omet izdelan: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Plasterer.update(dt) if not _G.state then return end; Plasterer.dayTimer=Plasterer.dayTimer+dt; if Plasterer.dayTimer>=30 then Plasterer.dayTimer=0; for i=#Plasterer.activeMaking,1,-1 do local m=Plasterer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Plasterer.completeMaking(m); table.remove(Plasterer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Plasterer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Plasterer.plasterer then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Plasterer.getStats() return {limeStock=Plasterer.limeStock,sandStock=Plasterer.sandStock,marbleStock=Plasterer.marbleStock,goldStock=Plasterer.goldStock,tileStock=Plasterer.tileStock,productStock=Plasterer.productStock,numBuildings=#Plasterer.buildings,hasPlasterer=Plasterer.plasterer~=nil,plastererName=Plasterer.plasterer and Plasterer.plasterer.name or "—",plastererSkill=Plasterer.plasterer and Plasterer.plasterer.skill or 0,activeMaking=#Plasterer.activeMaking,totalProducts=Plasterer.totalProducts} end
return Plasterer
